function IntakeQBtn({ patientName, date, forms }) {
  const [showModal, setShowModal] = React.useState(false);
  const [hoverAnswer, setHoverAnswer] = React.useState('');
  const [cachedForm, setCachedForm] = React.useState(null);
  const match = React.useMemo(() => matchIntakeQForm(patientName, date, forms), [patientName, date, forms]);
  const hasForm = !!match?.Id;

  // Pre-fetch as soon as match is found — so tooltip is ready on first hover
  React.useEffect(() => {
    if (!hasForm || hoverAnswer) return;
    fetch(`${INTAKEQ_WORKER}/form?intakeId=${match.Id}`)
      .then(r => r.json())
      .then(data => {
        setCachedForm(data);
        const keyQ = (data.Questions||[]).find(q => (q.Text||q.Question||'').trim() === 'Please select:');
        if (keyQ) setHoverAnswer((keyQ.Answer||keyQ.Value||'').slice(0, 80));
      }).catch(()=>{});
  }, [hasForm, match?.Id]);

  const handleClick = React.useCallback(() => {
    if (!match) return;
    setCachedForm(null);
    setShowModal(true);
  }, [match]);
  const title = hasForm
    ? (hoverAnswer ? `Retinal/OCT: ${hoverAnswer}` : 'Form submitted — click to view')
    : match ? 'Appointment found but no form yet' : 'No intake form found';
  return (
    <>
      <button onClick={handleClick}
        title={title}
        style={{background:'none',border:'none',cursor:match?'pointer':'default',fontSize:12,
          color: hasForm ? '#10B981' : '#CBD5E1', padding:'0 2px', lineHeight:1, opacity: match ? 1 : 0.4}}>
        📋
      </button>
      {showModal && match && <IntakeQFormModal form={match} onClose={() => setShowModal(false)}/>}
    </>
  );
}
const DEVICE_TO_LOC = {
  'santa clara ipad':'SC','fremont ipad':'F',
  'walnut creek ipad 2.0':'WC','sunnyvale ipad':'SV',
};
const DAY_ABB = ['Su','Mo','Tu','W','Th','F','Sa'];
const SVC_KEYS = ['exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherAmt2'];

function deviceToLoc(n) { return n?DEVICE_TO_LOC[n.toLowerCase().trim()]||null:null; }
function fmtShort(d) {
  if (!d) return '';
  const dt=new Date(d+'T12:00:00');
  return `${dt.getMonth()+1}/${dt.getDate()}/${String(dt.getFullYear()).slice(2)}`;
}
function dayAbb(d) { return d?DAY_ABB[new Date(d+'T12:00:00').getDay()]:''; }
function fmtTime(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'America/Los_Angeles'});
}
function squareNameSim(note,name) {
  if (!note||!name) return 0;
  const nt=note.toLowerCase().split(/[\s,]+/).filter(t=>t.length>1);
  const nm=name.toLowerCase().split(/[\s,]+/).filter(t=>t.length>1);
  if (!nm.length) return 0;
  return nm.filter(t=>nt.some(n=>n.includes(t)||t.includes(n))).length/nm.length;
}
function calcPtPaid(e) {
  return Math.max(0,['exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherAmt2'].reduce((s,k)=>s+(parseFloat(e[k])||0),0)-(parseFloat(e.discountAmount)||0));
}
function calcInsPaid(e) {
  return (parseFloat(e.insurancePaid1)||0)+(parseFloat(e.insurancePaid2)||0);
}
function findBillingMatch(docEntry,billingEntries) {
  if (!docEntry.patientName?.trim()) return null;
  const candidates=billingEntries.filter(b=>b.date===docEntry.date);
  if (!candidates.length) return null;
  const scored=candidates.map(b=>({b,score:squareNameSim(docEntry.patientName,b.patientName)}));
  const best=scored.sort((a,b)=>b.score-a.score)[0];
  return best?.score>=0.5?best.b:null;
}

function parseScheduleText(text) {
  const examPat=/\b(EP|NP|OV|RGP|Myopia|CL|EEX|ORTHO|MYO|BCL|CTC|DFE|OCT|LASIK|Topo|TRAIN|CK|RX)\b/i;
  const ignorePat=/^[\s(]|No Doctor|Lunch|\d{1,2}:\d{2}\s*(AM|PM)/i;
  const names=[]; const seen=new Set();
  for (const line of text.split('\n')) {
    for (const cell of line.split('\t')) {
      const t=cell.trim();
      if (!t||ignorePat.test(t)) continue;
      const m=t.match(examPat);
      if (m) {
        const name=t.slice(0,m.index).trim().replace(/[^a-zA-Z\s\-']/g,'').trim();
        if (name.length>2&&name.includes(' ')&&!seen.has(name.toLowerCase())) {
          seen.add(name.toLowerCase());
          const parts=name.trim().split(/\s+/);
          names.push(parts.length>=2?parts[parts.length-1]+', '+parts.slice(0,-1).join(' '):name);
        }
      }
    }
  }
  return names;
}

